BEGIN ATOMIC
 IF (SELECT count(*)<>200000 OR count_if(o.source_system IS DISTINCT FROM s.source_system OR o.type_id IS DISTINCT FROM s.type_id OR o.id IS DISTINCT FROM s.id OR o.logical_key_json IS DISTINCT FROM s.logical_key_json OR o.schema_revision IS DISTINCT FROM s.schema_revision OR o.entity_version IS DISTINCT FROM s.entity_version OR o.props_json IS DISTINCT FROM s.props_json OR o.retained_json IS DISTINCT FROM s.retained_json OR o.root_id IS DISTINCT FROM s.root_id OR o.source_feed IS DISTINCT FROM s.source_feed OR o.source_epoch IS DISTINCT FROM s.source_epoch OR o.source_position IS DISTINCT FROM s.source_position OR o.published_at IS DISTINCT FROM s.published_at)<>0 FROM client_dev.ashlar_scattered_20261005_n1.stage_n2 s LEFT JOIN client_dev.ashlar_scattered_20261005_n1.object_current o ON s.source_system=o.source_system AND s.type_id=o.type_id AND s.id=o.id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ashlar fused prior mismatch/cardinality'; END IF;
 MERGE INTO client_dev.ashlar_scattered_20261005_n1.object_current t USING client_dev.ashlar_scattered_20261005_n1.stage_n2 s ON t.source_system=s.source_system AND t.type_id=s.type_id AND t.id=s.id WHEN MATCHED THEN UPDATE SET t.props_json=s.new_props,t.entity_version=2,t.source_position=2,t.published_at=current_timestamp();
 INSERT INTO client_dev.ashlar_scattered_20261005_n1.property_journal SELECT 'pilot','object',1,id,103,2,'update',true,substring(to_json(array(get_json_object(props_json,'$.103'))),2,length(to_json(array(get_json_object(props_json,'$.103'))))-2),true,substring(to_json(array(get_json_object(new_props,'$.103'))),2,length(to_json(array(get_json_object(new_props,'$.103'))))-2),'r1','S','e',2,id,'synthetic-batch:2',current_timestamp() FROM client_dev.ashlar_scattered_20261005_n1.stage_n2;
 IF (SELECT count(*)<>200000 OR count_if(o.source_system IS DISTINCT FROM s.source_system OR o.type_id IS DISTINCT FROM s.type_id OR o.id IS DISTINCT FROM s.id OR o.logical_key_json IS DISTINCT FROM s.logical_key_json OR o.schema_revision IS DISTINCT FROM s.schema_revision OR o.retained_json IS DISTINCT FROM s.retained_json OR o.root_id IS DISTINCT FROM s.root_id OR o.source_feed IS DISTINCT FROM s.source_feed OR o.source_epoch IS DISTINCT FROM s.source_epoch OR o.props_json IS DISTINCT FROM s.new_props OR o.entity_version IS DISTINCT FROM 2 OR o.source_position IS DISTINCT FROM 2 OR o.published_at IS NULL OR j.id IS NULL OR j.property_id IS DISTINCT FROM 103 OR j.entity_version IS DISTINCT FROM 2 OR j.operation IS DISTINCT FROM 'update' OR j.old_present IS DISTINCT FROM true OR j.new_present IS DISTINCT FROM true OR j.schema_revision IS DISTINCT FROM 'r1' OR j.event_ordinal IS DISTINCT FROM s.id OR j.source_time_text IS DISTINCT FROM 'synthetic-batch:2' OR from_json(concat('[',j.old_json,']'),'ARRAY<STRING>')[0] IS DISTINCT FROM get_json_object(s.props_json,'$.103') OR from_json(concat('[',j.new_json,']'),'ARRAY<STRING>')[0] IS DISTINCT FROM get_json_object(s.new_props,'$.103'))<>0 FROM client_dev.ashlar_scattered_20261005_n1.stage_n2 s LEFT JOIN client_dev.ashlar_scattered_20261005_n1.object_current o ON s.source_system=o.source_system AND s.type_id=o.type_id AND s.id=o.id LEFT JOIN client_dev.ashlar_scattered_20261005_n1.property_journal j ON j.source_system=s.source_system AND j.entity_kind='object' AND j.type_id=s.type_id AND j.id=s.id AND j.source_feed='S' AND j.source_epoch='e' AND j.source_position=2) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ashlar fused canonical/journal mismatch/cardinality'; END IF;
 IF (SELECT count(*) FROM client_dev.ashlar_scattered_20261005_n1.property_journal WHERE source_feed='S' AND source_epoch='e' AND source_position=2)<>200000 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ashlar journal extra/missing event'; END IF;
 INSERT INTO client_dev.ashlar_scattered_20261005_n1.receipt VALUES (2,current_timestamp());
 END
